 scene=new THREE.Scene();camera=new THREE.OrthographicCamera(-4,4,3,-3,.01,100);camera.position.set(4.5,3.5,-5.3);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.10;controls.minZoom=.15;controls.maxZoom=15;controls.autoRotateSpeed=.65;controls.maxPolarAngle=Math.PI*.95;controls.target.set(0,0,0);
 scene.add(new THREE.HemisphereLight(0xffffff,0x849075,1.65));keyLight=new THREE.DirectionalLight(0xfff7e9,2.8);keyLight.position.set(-3,9,-3);keyLight.castShadow=true;keyLight.shadow.mapSize.set(2048,2048);Object.assign(keyLight.shadow.camera,{left:-5,right:5,top:5,bottom:-5,near:.1,far:25});keyLight.shadow.normalBias=.015;keyLight.shadow.bias=-.0002;scene.add(keyLight);const fill=new THREE.DirectionalLight(0xe4edff,1.1);fill.position.set(4,3,4);scene.add(fill);
 for(const m of data.meshes){const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(new Float32Array(binary,m.positions.offset,m.positions.count),3));geo.setAttribute('normal',new THREE.BufferAttribute(new Float32Array(binary,m.normals.offset,m.normals.count),3));geo.setIndex(new THREE.BufferAttribute(new Uint32Array(binary,m.indices.offset,m.indices.count),1));geo.computeBoundingSphere();const mat=new THREE.MeshStandardMaterial({color:baseColor(m),roughness:/loi_/.test(m.name)?.32:.65,metalness:/loi_/.test(m.name)?.5:.14,side:THREE.DoubleSide});const mesh=new THREE.Mesh(geo,mat);mesh.castShadow=true;mesh.receiveShadow=true;const edge=new THREE.LineSegments(new THREE.EdgesGeometry(geo,32),new THREE.LineBasicMaterial({color:0x687460,transparent:true,opacity:.32}));mesh.add(edge);mesh.userData={...m,edges:edge,explodeVector:explodeVector(m)};meshes.push(mesh);scene.add(mesh)}
